// Source: test_solved_intervals, ten real mj_step intervals per topology.
[[gnu::noinline]] void test_solved_intervals() {
    for (auto mode : {"crank_effort", "articulated_effort"}) for (bool sparse : {false, true})
        for (auto kind : kinds) for (auto topology : {"plain", "clutch", "rotor"}) {
            if (kind == "elastic_chain" && std::string_view(topology) != "plain") continue;
            auto golden = node("test_solved_intervals", std::string(mode) + "-" + (sparse ? "sparse-" : "dense-") +
                std::string(kind) + "-" + topology);
            auto owner = pair(kind, mode, topology, sparse);
            for (int i = 0; i < 10; ++i) {
                const auto forces = components(*owner, .0002, 2., {}, true, false, true, 20.);
                components(golden, forces); tree(golden, diagnostics(*owner)); step(*owner, forces);
                array(golden, owner->drive().settle()); tree(golden, diagnostics(*owner));
                array(golden, owner->qpos()); array(golden, owner->qvel()); state(golden, *owner);
            }
            golden.done();
        }
}
// Source: test_atomic_state_inputs_and_probes.
[[gnu::noinline]] void test_atomic_state_inputs_and_probes() {
    auto golden = node("test_atomic_state_inputs_and_probes"); auto owner = pair("geometric_ideal_mid_drive");
    const auto before = state(*owner);
    components(golden, components(*owner, .002, 2., {}, true, false, false));
    tree(golden, diagnostics(*owner, true)); tree(golden, field(state(*owner), "policies"));
    bt::require(bike::io::canonical_json(field(state(*owner), "policies")) == bike::io::canonical_json(field(before, "policies")),
        "probe preserves every live policy");
    const auto saved = state(*owner); restore(*owner, saved); state(golden, *owner);
    auto broken = saved; put(member(broken, "policies"), "battery", "energy_j", Value{bike::io::Number{"nan"}});
    bt::invalid([&] { restore(*owner, broken); }); state(golden, *owner);
    const std::vector<double> control(owner->ctrl().begin(), owner->ctrl().end());
    bt::invalid([&] { owner->set_inputs(std::vector<double>(control.size(), 1.),
        std::vector<double>(owner->qvel().size(), std::numeric_limits<double>::infinity())); });
    array(golden, owner->ctrl()); golden.done();
}
