// Source: test_transmission_core, six independent reset/prepare/ratio cases.
[[gnu::noinline]] void test_transmission_core() {
    for (auto operation : {"reset", "prepare", "ratio"}) for (auto kind : {"ideal_mid_drive", "geometric_ideal_mid_drive"}) {
        auto golden = node("test_transmission_core", std::string(operation) + "-" + kind);
        auto owner = bare(model_xml(kind));
        const std::array position{.12, .15, 40., .006, 46., -.2, .1, .2};
        owner->set_state(position, std::vector<double>(8), {}, std::vector<double>(8), .3); owner->forward();
        const bool geometric = std::string_view(kind) == "geometric_ideal_mid_drive";
        auto transmission = std::make_unique<drivetrain::Transmission>(owner->model(),
            drivetrain::GearingConfig{34, 24, .0127}, geometric,
            geometric ? "geometric_mid_drive_freehub" : "ideal_mid_drive_freehub");
        if (std::string_view(operation) == "ratio") {
            transmission->reset(owner->data()); transmission->set_ratio(owner->data(), 34. / 28.);
        } else if (std::string_view(operation) == "reset") transmission->reset(owner->data());
        else transmission->prepare(owner->data());
        const auto actual = std::make_unique<drivetrain::TransmissionSnapshot>(transmission->state());
        bt::require(actual->boundary.has_value(), "transmission operation establishes a ratchet boundary");
        scalar(golden, *actual->boundary); scalar(golden, actual->ratio); array(golden, actual->range); array(golden, actual->coefficients);
        if (geometric) {
            bt::require(actual->prepared.has_value(), "geometric operation prepares the full linearization");
            scalar(golden, actual->prepared->phi); array(golden, actual->prepared->jacobian);
            array(golden, actual->prepared->qpos); scalar(golden, actual->prepared->time);
        }
        golden.done();
    }
}
