// Source: test_shifting_prepared_state_and_clock, four contact/slip conditions.
[[gnu::noinline]] void test_shifting_prepared_state_and_clock() {
    struct Contact { std::string_view id; bool contact; std::optional<double> slip; };
    const std::array contacts{Contact{"contact", true, {}}, Contact{"airborne", false, {}},
        Contact{"slip-positive", true, 5.}, Contact{"slip-negative", true, -5.}};
    for (const auto& item : contacts) for (auto kind : {"ideal_mid_drive", "geometric_ideal_mid_drive"}) {
        auto golden = node("test_shifting_prepared_state_and_clock", std::string(item.id) + "-" + kind);
        auto input = source(kind); input.shifting.enabled = true; input.shifting.cadence_smoothing_tau_s = 0.;
        input.shifting.shift_cooldown_s = .3; input.shifting.shift_cut_duration_s = .1; input.pedaling.enabled = true;
        auto owner = pair(input); velocity(*owner, "crank_spin", 15.); velocity(*owner, "rear_wheel_spin", 25.);
        reset_engine_state(*owner);
        for (int i = 0; i < 4; ++i) {
            const auto pedal = owner->drive().prepare({}, .15, false, true, true, item.contact, item.slip, 7.);
            tree(golden, policy_reference::pedaling_result(pedal)); state(golden, *owner);
            array(golden, owner->qpos()); array(golden, owner->qvel());
            components(golden, components(*owner, .15, 2., {}, true, false, true, 0., pedal)); state(golden, *owner);
            error<std::invalid_argument>([&] { (void)components(*owner, .15, 2.); }, "once per timestamp");
            clear_pending(*owner); owner->data()->time += .15; reset_engine_state(*owner);
        }
        const auto old = state(*owner); owner->drive().restart_clock(); state(golden, *owner);
        tree(golden, field(field(state(*owner), "policies"), "battery"));
        bt::require(bike::io::canonical_json(field(field(state(*owner), "policies"), "battery")) ==
            bike::io::canonical_json(field(field(old, "policies"), "battery")), "clock restart preserves battery inventory");
        owner->drive().reset(); state(golden, *owner); golden.done();
    }
}
