            components(golden, components(*owner, .002, 2., {}, item.active, item.braking, false));
            tree(golden, diagnostics(*owner, true)); array(golden, owner->ctrl());
            auto saved = state(*owner); set(saved, "probe_last", field(before, "probe_last")); tree(golden, saved);
            bt::require(bike::io::canonical_json(saved) == bike::io::canonical_json(before), "probe leaves every live ratchet and policy unchanged");
