// Source: test_invalid_calls_are_atomic. The three Python-only type tests
// for braking/active/advance are separate inventory drops: native TickInputs
// stores bool and has no dynamic-call keyword adapter. The other six inputs
// exercise the native call / owned public-control decoder, then the same
// state and actuator snapshots as the original test.
[[gnu::noinline]] void test_invalid_calls_are_atomic() {
    for (auto id : {"dt-zero", "dt-nan", "speed-infinite", "sensed-nan", "rider-integer", "motor-limit-negative"}) {
        auto golden = node("test_invalid_calls_are_atomic", id); auto owner = pair();
        const auto before = state(*owner);
        bt::invalid([&] {
            const std::string_view which(id);
            if (which == "rider-integer") {
                auto control = rider::encode_intent_control(rider::IntentControl{});
                set(control, "rider_enabled", integer(1));
                (void)rider::decode_intent_control(control, "control");
            } else {
                drivetrain::TickInputs input; input.dt = .002; input.speed = 2.;
                if (which == "dt-zero") input.dt = 0.;
                else if (which == "dt-nan") input.dt = std::numeric_limits<double>::quiet_NaN();
                else if (which == "speed-infinite") input.speed = std::numeric_limits<double>::infinity();
                else if (which == "sensed-nan") input.sensed = std::numeric_limits<double>::quiet_NaN();
                else input.control.motor_limit_nm = -1.;
                (void)owner->drive().stage_components(input);
            }
        });
        state(golden, *owner); array(golden, owner->ctrl());
        bt::require(bike::io::canonical_json(state(*owner)) == bike::io::canonical_json(before), "invalid call publishes no state");
        golden.done();
    }
}
// Source: test_invalid_restoration_is_atomic; every source malformed member.
[[gnu::noinline]] void test_invalid_restoration_is_atomic() {
    struct Bad { std::string_view id, section, key; Value value; };
    const std::vector<Bad> cases{
        {"angles-width", "root", "angles", Value{Value::Array{real(0.), real(1.)}}},
        {"reference-nan", "root", "reference", Value{bike::io::Number{"nan"}}},
        {"time-infinite", "root", "last_time_s", Value{bike::io::Number{"inf"}}},
        {"ratio-zero", "ideal_hub", "ratio", real(0.)}, {"pending-integer", "ideal_hub", "shift_pending", integer(1)},
        {"coefficient-width", "ideal_hub", "coefficients", Value{Value::Array{real(0.)}}},
        {"count-overflow", "shifting", "shift_count", integer(std::int64_t{1} << 40)},
        {"coasting-integer", "pedaling", "coasting", integer(1)}, {"direction", "shifting", "direction", text("bad")},
        {"battery-negative", "battery", "energy_j", real(-1.)}, {"assist-nan", "assist", "torque", Value{bike::io::Number{"nan"}}}};
    for (const auto& item : cases) {
        auto golden = node("test_invalid_restoration_is_atomic", item.id); auto owner = pair("geometric_ideal_mid_drive");
        const auto before = state(*owner); auto candidate = before;
        Value& target = item.section == "root" ? candidate : item.section == "ideal_hub" ? member(candidate, item.section) :
            member(member(candidate, "policies"), item.section);
        set(target, item.key, item.value); bt::invalid([&] { restore(*owner, candidate); }); state(golden, *owner);
        bt::require(bike::io::canonical_json(state(*owner)) == bike::io::canonical_json(before), "malformed restore is atomic");
        golden.done();
    }
}
// Source: test_set_inputs_cross_aliases_and_ownership, all three rejections.
[[gnu::noinline]] void test_set_inputs_cross_aliases_and_ownership() {
    auto golden = node("test_set_inputs_cross_aliases_and_ownership"); auto owner = pair();
    std::vector<double> initial(owner->qvel().size());
    for (std::size_t i = 0; i < initial.size(); ++i) initial[i] = static_cast<double>(i) + 1.;
    const std::array control{17., 18.}; owner->set_inputs(control, initial);
    owner->set_inputs(owner->qfrc_applied().first(control.size()), owner->qfrc_applied());
    array(golden, owner->ctrl()); array(golden, owner->qfrc_applied());
    for (int bad = 0; bad < 3; ++bad) {
        bt::invalid([&] {
            if (bad == 0) owner->set_inputs(std::array{0.}, initial);
            else if (bad == 1) owner->set_inputs(control, std::array{0.});
            else owner->set_inputs(control, std::vector<double>(initial.size(), std::numeric_limits<double>::quiet_NaN()));
        });
        array(golden, owner->ctrl()); array(golden, owner->qfrc_applied());
    }
    const auto owned_components = components(*owner, .002, 2.);
    owner.reset(); components(golden, owned_components); golden.done();
}
// Source: test_injected_valid_state_and_replay, full eight-interval continuation.
[[gnu::noinline]] void test_injected_valid_state_and_replay() {
    for (auto kind : kinds) {
        auto golden = node("test_injected_valid_state_and_replay", kind); auto owner = pair(kind);
        auto injected = std::make_unique<drivetrain::DriveSnapshot>(owner->drive().state());
        injected->pedaling.effort = 13.; injected->pedaling.cadence_ema = -3.;
        injected->shifting.cooldown_s = .07; injected->shifting.cut_remaining_s = .03;
        injected->shifting.shift_count = 4; injected->shifting.direction = "up"; injected->shifting.from_teeth = 28;
        injected->assist.torque = 2.; injected->assist.last_gain = .4;
        injected->battery.energy_j = 17.; injected->battery.drawn_energy_j = 3.;
        injected->shift_time_s = -1.; injected->last_time_s = -.5;
        bt::require(injected->angles.has_value(), "injected source has angle state");
        for (auto& angle : std::span(injected->angles->values).first(injected->angles->count)) angle += 2. * std::numbers::pi;
        if (injected->hub) {
            injected->hub->boundary = -.03; injected->hub->energy_j = .04; injected->hub->torque_nm = 2.;
            injected->reference.value() += .001;
        }
        if (injected->ideal_hub) {
            injected->ideal_hub->boundary.value() += .02;
            if (kind == "geometric_ideal_mid_drive") {
                injected->ideal_hub->last_tension_n = 2.; injected->ideal_hub->shift_pending = true;
                injected->ideal_hub->shift_parameter_work_j = -.1; injected->ideal_hub->shift_constraint_work_j = .2;
            }
        }
        owner->drive().restore(*injected); state(golden, *owner);
        injected->battery.energy_j = 999.;
        bt::require(owner->drive().battery_energy_j() == 17., "restore owns the caller's battery state");
        for (int i = 0; i < 8; ++i) {
            const auto forces = components(*owner, .0002, 2.); components(golden, forces); state(golden, *owner);
            step(*owner, forces); array(golden, owner->drive().settle()); state(golden, *owner);
        }
        golden.done();
    }
}
// Source: test_pending_and_duplicate_settlement_guards.
[[gnu::noinline]] void test_pending_and_duplicate_settlement_guards() {
    for (auto kind : {"ideal_mid_drive", "geometric_ideal_mid_drive"}) {
        auto golden = node("test_pending_and_duplicate_settlement_guards", kind); auto owner = pair(kind);
        (void)components(*owner, .0002, 2.);
        const std::vector<double> controls(owner->ctrl().begin(), owner->ctrl().end());
        owner->data()->time = .1; reset_engine_state(*owner);
        error<std::runtime_error>([&] { (void)components(*owner, .0002, 2.); }, "not settled");
        state(golden, *owner);
        // set_state resets ctrl; the source next supplies the oracle's saved
        // actuator inputs from that first components call.
        owner->set_inputs(controls, std::vector<double>(owner->qvel().size())); owner->step();
        array(golden, owner->drive().settle()); const auto first = state(*owner);
        array(golden, owner->drive().settle()); state(golden, *owner);
        tree(golden, field(field(state(*owner), "policies"), "battery"));
        bt::require(bike::io::canonical_json(field(field(state(*owner), "policies"), "battery")) ==
            bike::io::canonical_json(field(field(first, "policies"), "battery")), "duplicate settle cannot debit battery twice");
        golden.done();
    }
}
